"""
Use for easier frames translation, dowload complete frames from https://www.pixilart.com/draw, upload it to https://newbiely.com/online-tool/image-to-bitmap-converter, copy paste the result into bitmap list 
"""


def divideFrames(completeFrame, frames):
            
    totalWidth = WIDTH * frames
    
    for i in range(frames):
        frame = []
        for row in range(HEIGHT):
            start = row * totalWidth + i * WIDTH
            end = start + WIDTH
            frame.extend(completeFrame[start:end])
        frameList.append(frame)

    
def tftArrayOfFrames(frames, file_name):
    text = f"const uint16_t {file_name}[{len(frames)}][{WIDTH*HEIGHT}] PROGMEM = {{"

    for f in frames:
        text += "\n{"
        for i in range(0, len(f), 16):
            # swap R and B channels then byte swap
            bgr_swapped = []
            for v in f[i:i+16]:
                r = (v >> 11) & 0x1F
                g = (v >> 5)  & 0x3F
                b = (v)       & 0x1F
                bgr = (b << 11) | (g << 5) | r
                swapped = ((bgr & 0xFF) << 8) | ((bgr >> 8) & 0xFF)
                bgr_swapped.append(swapped)

            text += " " + ", ".join(f"0x{v:04X}" for v in bgr_swapped)

            if(i+16 != len(f)):   
                text += ", "
            
        text += "},\n" if f != frames[-1] else "}\n"
    
    text += "};"

    with open(dir_name+"/"+file_name, "a", encoding="utf-8") as f:
            f.write(text)

    
"""
This is only for Oled since TFT can do uint16_t rather than uint8_t
"""
def arrayPerFrame(frames, file_name):
    count = 0
    for f in frames:

        result = []
        for row in range(HEIGHT):
            byte = 0
            bit_count = 0
            for col in range(WIDTH):
                pixel = f[row * WIDTH + col] #row * width to skip
                bit = 1 if pixel > 0 else 0
                byte = (byte << 1) | bit
                bit_count += 1
                if bit_count == 8:
                    result.append(f"0x{byte:02X}")
                    byte = 0
                    bit_count = 0

        text = f"const uint8_t {file_name+str(count)}[] PROGMEM = {{"
        for i in range(0, len(result), 16):
            text += "  " + ", ".join(result[i:i+16]) + ","
        text += "};\n"

        with open(dir_name+"/"+file_name, "a", encoding="utf-8") as f:
            f.write(text)

def arrayOfFrames(frames, file_name):
    text = f"const uint8_t {file_name}[{len(frames)}][{WIDTH*HEIGHT}] PROGMEM = {{"
    count = 0
    for f in frames:

        result = []
        for row in range(HEIGHT):
            byte = 0
            bit_count = 0
            for col in range(WIDTH):
                pixel = f[row * WIDTH + col] #row * width to skip
                bit = 1 if pixel > 0 else 0
                byte = (byte << 1) | bit
                bit_count += 1
                if bit_count == 8:
                    result.append(f"0x{byte:02X}")
                    byte = 0
                    bit_count = 0

        text += "{"
        for i in range(0, len(result), 16):
            text += " " + ", ".join(result[i:i+16]) 
            if(count != len(frames)-1):
                text += ", "

        text += "},\n"
    
    text += "};"

    with open(dir_name+"/"+file_name, "a", encoding="utf-8") as f:
            f.write(text)

